package com.ibm.advocacy.service;
import com.ibm.advocacy.model.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.ibm.advocacy.model.MetricsSchema.*;
class ReportingRuleCorrectionTest {
 Row row(String id,String name,String author,String tool){return new Row(id,new LinkedHashMap<>(Map.of("Date","2026-09-14","Author",author,"Tool",tool,"Name of activity",name,"Type of activity","Blog post / slide shares / .io updates",URL,"https://dzone.com/articles/agent-memory-storage")));}
 @Test void identityNormalizesEncodingButPreservesSeparateActivities(){Row old=row("old","Agent\u0092s Memory","Markus","IBM Bob"),now=row("now","Agent’s Memory","Markus","IBM Bob");now.cells.put("Event","DZone.com");assertEquals(TrailingReporting.activityKey(old),TrailingReporting.activityKey(now));now.cells.put("Activity stage","Delivery");assertNotEquals(TrailingReporting.activityKey(old),TrailingReporting.activityKey(now));now.cells.remove("Activity stage");now.cells.put("Date","2026-07-14");assertNotEquals(TrailingReporting.activityKey(old),TrailingReporting.activityKey(now));}
 @Test void duplicateAttributionsDoNotHalveTheResourceAgain(){Row old=row("old","Agent\u0092s Memory","Markus","IBM Bob"),now=row("now","Agent’s Memory","Markus","IBM Bob");old.cells.put("Current total","2100");now.cells.put("Current total","0");now.cells.put("Event","DZone.com");String url=old.get(URL);var result=Calculations.trailing(List.of(old,now),Map.of(url,new Measurement("2300","VIEWS",url,"2026-10-12T12:00:00Z","Counter",false)));assertEquals("2300",result.getFirst().get("Current total"));assertEquals("200",result.getFirst().get(VIEWS));assertEquals("Yes",result.getLast().get("Duplicate collection attribution"));}
 Row legacy(String id,String tool){Row row=row(id,"Shared article","Alex",tool);row.cells.put("Current total","117");row.cells.put("Previous total","91");row.cells.put(VIEWS,"13");row.cells.put("Legacy views formula","(Table1[[#This Row],[Current total]]-Table1[[#This Row],[Previous total]])/2");return row;}
 @Test void legacyNormalizationRequiresFormulaAndMatchingGroupEvidence(){Row a=legacy("a","IBM Bob"),b=legacy("b","IBM Runtimes");Data result=LegacyBaselineAllocation.normalize(Data.output(new Data(),List.of(a,b)));assertTrue(result.rows.stream().allMatch(row->row.get("Current total").equals("58.5")&&row.get("Previous total").equals("45.5")&&row.get(VIEWS).equals("13")));assertEquals("117",a.get("Current total"));result.rows.forEach(row->row.cells.put("Source run","published"));assertEquals("58.5",LegacyBaselineAllocation.normalize(result).rows.getFirst().get("Current total"));assertFalse(LegacyBaselineAllocation.normalize(Data.output(new Data(),List.of(a))).rows.getFirst().get("Baseline allocation issue").isBlank());Row allocated=legacy("done","IBM Bob");allocated.cells.remove("Legacy views formula");allocated.cells.put("Current total","58.5");assertEquals("58.5",LegacyBaselineAllocation.normalize(Data.output(new Data(),List.of(allocated))).rows.getFirst().get("Current total"));}
 @Test void verifiedSeptemberTotalsUse6433BaselineAndDoNotPretendToScrape(){Run run=new Run();run.workbook.put("month","2026-09");Row source=row("webinar","Use Bob","Markus","IBM Bob");source.cells.put("Verified reporting month","2026-09");source.cells.put("Current total","9533");source.cells.put("Previous total","6433");Row result=source.copy();assertTrue(VerifiedMonthlyTotals.matches(run,source));VerifiedMonthlyTotals.apply(run,source,result);assertEquals("3100",result.get(VIEWS));assertEquals("6433",result.get("Previous total"));assertEquals("",result.get("Measured at"));run.workbook.put("month","2026-10");assertFalse(VerifiedMonthlyTotals.matches(run,source));source.cells.put("Previous total","10000");assertThrows(IllegalArgumentException.class,()->VerifiedMonthlyTotals.apply(run,source,source.copy()));}
}
